\textbf{ĐÁP ÁN BÀI 1.} \textbf{(1,5 điểm)} Đặt tính rồi tính: [[br]]
\noindent\begin{minipage}[t]{0.48\linewidth}
\textbf{a)} $274\,806 + 351\,457$
\end{minipage}\hfill
\begin{minipage}[t]{0.48\linewidth}
\textbf{b)} $167\,285 - 96\,546$
\end{minipage} [[br]] \textbf{a) (0,75đ)} $274\,806 + 351\,457 = 626\,263$. [[br]] \textbf{b) (0,75đ)} $167\,285 - 96\,546 = 70\,739$. [[br]] Mỗi ý: đặt tính đúng $0,25$đ, kết quả đúng $0,5$đ. [[br]] \textit{(Nguồn: Đề CK1 TH Hồng Quang, Ứng Hòa, Hà Nội 2024-2025.)}

\textbf{ĐÁP ÁN BÀI 2.} \textbf{(2,0 điểm)} Tính bằng cách thuận tiện: [[br]]
\noindent\begin{minipage}[t]{0.48\linewidth}
\textbf{a)} $2\,023 + 1\,736 - 23 + 1\,264$
\end{minipage}\hfill
\begin{minipage}[t]{0.48\linewidth}
\textbf{b)} $1\,537 + 576 - 537 + 424$
\end{minipage} [[br]] \textbf{a) (1,0đ)} $= (2\,023 - 23) + (1\,736 + 1\,264) = 2\,000 + 3\,000 = 5\,000$. [[br]] \textbf{b) (1,0đ)} $= (1\,537 - 537) + (576 + 424) = 1\,000 + 1\,000 = 2\,000$. [[br]] \textit{Nhóm đúng $0,5$đ, kết quả đúng $0,5$đ mỗi ý.} [[br]] \textit{(Nguồn: a) TH Thị trấn Lộc Hà, Hà Tĩnh 2024-2025; b) TH Trần Quốc Toản, Đắk Lắk 2025-2026.)}

